    public StatBlock Add(StatBlock other) => new StatBlock(
        SaturatingAdd(MaxHp, other.MaxHp),
        SaturatingAdd(MaxMp, other.MaxMp),
        SaturatingAdd(Attack, other.Attack),
        SaturatingAdd(Defense, other.Defense),
        SaturatingAdd(Magic, other.Magic),
        SaturatingAdd(Resistance, other.Resistance),
        SaturatingAdd(Speed, other.Speed),
        SaturatingAdd(Luck, other.Luck)).Clamp();

    private static int SaturatingAdd(int left, int right) =>
        (int)Math.Clamp((long)left + right, int.MinValue, int.MaxValue);
}

