public interface IExperienceCurve
{
    ulong TotalExperienceForLevel(ushort level);
}

public sealed class QuadraticExperienceCurve : IExperienceCurve
{
    public ulong Base { get; init; } = 100;
    public ulong Growth { get; init; } = 25;

    public ulong TotalExperienceForLevel(ushort level)
    {
        var completed = (ulong)Math.Max(0, level - 1);
        var prior = completed == 0 ? 0 : completed - 1;
        return checked(Base * completed + Growth * completed * prior / 2);
    }
}

