public sealed class Inventory
{
    public int DistinctCapacity { get; init; } = 256;
    public Dictionary<string, uint> Stacks { get; init; } = new(StringComparer.Ordinal);

    public uint Quantity(string itemId) => Stacks.GetValueOrDefault(itemId);

    public uint Add(ItemDefinition item, uint quantity)
    {
        item.Validate();
        if (quantity == 0) return Quantity(item.Id);
        if (!Stacks.ContainsKey(item.Id) && Stacks.Count >= DistinctCapacity)
            throw new InvalidOperationException("Inventory distinct-item capacity reached.");
        var next = checked(Quantity(item.Id) + quantity);
        if (next > item.StackLimit)
            throw new InvalidOperationException($"Item '{item.Id}' stack exceeds {item.StackLimit}.");
        Stacks[item.Id] = next;
        return next;
    }

    public uint Remove(string itemId, uint quantity)
    {
        var current = Quantity(itemId);
        if (quantity > current)
            throw new InvalidOperationException($"Not enough '{itemId}'.");
        var remaining = current - quantity;
        if (remaining == 0) Stacks.Remove(itemId);
        else Stacks[itemId] = remaining;
        return remaining;
    }

    public string? Equip(
        CharacterProgress actor,
        ItemDefinition item,
        IReadOnlyDictionary<string, ItemDefinition> definitions)
    {
        var equipment = item.Equipment ??
            throw new InvalidOperationException($"Item '{item.Id}' is not equipment.");
        if (Quantity(item.Id) == 0)
            throw new InvalidOperationException($"Not enough '{item.Id}'.");
        actor.Equipment.TryGetValue(equipment.Slot, out var previous);
        ItemDefinition? previousDefinition = null;
        if (previous != null)
        {
            if (!definitions.TryGetValue(previous, out previousDefinition))
                throw new InvalidOperationException($"Unknown equipped item '{previous}'.");
            if (Quantity(previous) >= previousDefinition.StackLimit)
                throw new InvalidOperationException($"Cannot return '{previous}' to a full stack.");
        }
        Remove(item.Id, 1);
        actor.Equipment[equipment.Slot] = item.Id;
        if (previousDefinition != null) Add(previousDefinition, 1);
        return previous;
    }
}

