    public void Recruit(CharacterProgress actor, bool preferActive = true)
    {
        if (!Actors.TryAdd(actor.ActorId, actor))
            throw new InvalidOperationException($"Actor '{actor.ActorId}' is already recruited.");
        if (preferActive && Active.Count < ActiveLimit) Active.Add(actor.ActorId);
        else Reserve.Add(actor.ActorId);
    }

    public void SetActive(IEnumerable<string> actorIds)
    {
        var requested = actorIds.ToList();
        if (requested.Count > ActiveLimit || requested.Distinct(StringComparer.Ordinal).Count() != requested.Count)
            throw new InvalidOperationException("Active party is too large or contains duplicates.");
        if (requested.Any(id => !Actors.ContainsKey(id)))
            throw new InvalidOperationException("Active party contains an unknown actor.");
        Active.Clear();
        Active.AddRange(requested);
        Reserve.Clear();
        Reserve.AddRange(Actors.Keys.Where(id => !Active.Contains(id, StringComparer.Ordinal)));
    }

    public void GrantCurrency(ulong amount) => Currency = checked(Currency + amount);

    public void SpendCurrency(ulong amount)
    {
        if (amount > Currency) throw new InvalidOperationException("Not enough currency.");
        Currency -= amount;
    }
}

