public interface IBattleFormula
{
    int Damage(StatBlock attacker, StatBlock target, int power, DamageKind kind);
    int Healing(StatBlock caster, int power);
}

public sealed class ClassicBattleFormula : IBattleFormula
{
    public int Damage(StatBlock attacker, StatBlock target, int power, DamageKind kind)
    {
        if (kind == DamageKind.Direct) return Math.Max(0, power);
        var offense = kind == DamageKind.Physical ? attacker.Attack : attacker.Magic;
        var defense = kind == DamageKind.Physical ? target.Defense : target.Resistance;
        return Math.Max(1, SaturatingMultiply(offense, Math.Max(0, power)) / 100 - defense / 2);
    }

    public int Healing(StatBlock caster, int power) =>
        Math.Max(1, SaturatingMultiply(caster.Magic, Math.Max(0, power)) / 100);

    private static int SaturatingMultiply(int left, int right) =>
        (int)Math.Clamp((long)left * right, int.MinValue, int.MaxValue);
}

public sealed class BattleSession
{
    public BattlePhase Phase { get; private set; } = BattlePhase.Running;
    public uint AtbThreshold { get; init; } = 10_000;
    public Dictionary<string, BattleUnit> Units { get; init; } = new(StringComparer.Ordinal);
    public HashSet<string> Ready { get; init; } = new(StringComparer.Ordinal);
    public Queue<BattleCommand> Commands { get; init; } = new();

    public BattleSession() { }

    public BattleSession(IEnumerable<BattleUnit> units)
    {
        foreach (var unit in units)
            if (!Units.TryAdd(unit.Id, unit))
                throw new InvalidOperationException($"Duplicate battle unit '{unit.Id}'.");
        if (!Units.Values.Any(unit => unit.Side == BattleSide.Party) ||
            !Units.Values.Any(unit => unit.Side == BattleSide.Enemy))
            throw new InvalidOperationException("Battle requires party and enemy units.");
    }

    public IReadOnlyList<BattleEvent> AdvanceTime(uint deltaMilliseconds)
    {
        var events = new List<BattleEvent>();
        if (Phase != BattlePhase.Running) return events;
        foreach (var unit in Units.Values.OrderBy(unit => unit.Id, StringComparer.Ordinal))
        {
            if (!unit.Alive || Ready.Contains(unit.Id)) continue;
            unit.Atb = Math.Min(
                AtbThreshold,
                SaturatingAdd(unit.Atb, SaturatingMultiply((uint)Math.Max(1, unit.Stats.Speed), deltaMilliseconds)));
            if (unit.Atb >= AtbThreshold)
            {
                Ready.Add(unit.Id);
                events.Add(new BattleEvent("unit_ready", TargetId: unit.Id));
            }
        }
        return events;
    }

    public BattleEvent GrantTurn(string unitId)
    {
        var unit = GetUnit(unitId);
        if (!unit.Alive) throw new InvalidOperationException($"Unit '{unitId}' is defeated.");
        unit.Atb = AtbThreshold;
        Ready.Add(unitId);
        return new BattleEvent("unit_ready", TargetId: unitId);
    }

    public BattleEvent Queue(
        BattleCommand command,
        IReadOnlyDictionary<string, AbilityDefinition> abilities)
    {
        if (Phase != BattlePhase.Running) throw new InvalidOperationException("Battle has ended.");
        var actor = GetUnit(command.ActorId);
        if (!actor.Alive || !Ready.Contains(actor.Id))
            throw new InvalidOperationException($"Unit '{actor.Id}' is not ready.");
        if (!abilities.TryGetValue(command.AbilityId, out var ability))
            throw new KeyNotFoundException($"Unknown ability '{command.AbilityId}'.");
        ability.Validate();
        if (actor.Mp < ability.MpCost)
            throw new InvalidOperationException($"Unit '{actor.Id}' does not have enough MP.");
        if (!TargetsValid(actor, ability.TargetRule, command.TargetIds))
            throw new InvalidOperationException($"Invalid targets for '{ability.Id}'.");
        Ready.Remove(actor.Id);
        Commands.Enqueue(command);
        return new BattleEvent("command_queued", actor.Id, DefinitionId: ability.Id);
    }

    public IReadOnlyList<BattleEvent> ExecuteNext(
        IReadOnlyDictionary<string, AbilityDefinition> abilities,
        IReadOnlyDictionary<string, StatusDefinition> statuses,
        DeterministicRandom random,
        IBattleFormula? formula = null)
    {
        formula ??= new ClassicBattleFormula();
        var events = new List<BattleEvent>();
        if (Commands.Count == 0) return events;
        var command = Commands.Dequeue();
        var actor = GetUnit(command.ActorId);
        var ability = abilities[command.AbilityId];
        if (!actor.Alive) throw new InvalidOperationException($"Unit '{actor.Id}' is defeated.");
        actor.Mp -= ability.MpCost;
        if (ability.MpCost > 0)
            events.Add(new BattleEvent("mp_spent", actor.Id, Amount: ability.MpCost));
        var actorStats = actor.ResolveStats(statuses);
        foreach (var targetId in command.TargetIds)
            foreach (var effect in ability.Effects)
                ApplyEffect(actor, actorStats, GetUnit(targetId), ability, effect, statuses, random, formula, events);
        actor.Atb = 0;
        actor.Defending = false;
        TickStatuses(actor, statuses, random, formula, events);
        RefreshPhase(events);
        return events;
    }

    private void ApplyEffect(
        BattleUnit actor,
        StatBlock actorStats,
        BattleUnit target,
        AbilityDefinition ability,
        BattleEffect effect,
        IReadOnlyDictionary<string, StatusDefinition> statuses,
        DeterministicRandom random,
        IBattleFormula formula,
        List<BattleEvent> events)
    {
        switch (effect)
        {
            case DamageEffect damage:
                if (random.RollBasisPoints() >= ability.AccuracyBasisPoints)
                {
                    events.Add(new BattleEvent("missed", actor.Id, target.Id));
                    return;
                }
                var critical = random.RollBasisPoints() < ability.CriticalBasisPoints;
                var amount = formula.Damage(actorStats, target.ResolveStats(statuses), damage.Power, damage.Kind);
                amount = Scale(amount, target.ElementAffinityBasisPoints.GetValueOrDefault(damage.Element, 10_000));
                if (critical) amount = SaturatingMultiply(amount, 3) / 2;
                if (target.Defending) amount /= 2;
                target.Hp = Math.Max(0, target.Hp - amount);
                events.Add(new BattleEvent("damaged", actor.Id, target.Id, Amount: amount, Critical: critical));
                if (!target.Alive)
                {
                    target.Atb = 0;
                    Ready.Remove(target.Id);
                    events.Add(new BattleEvent("unit_defeated", actor.Id, target.Id));
                }
                break;
            case HealEffect heal:
                var before = target.Hp;
                target.Hp = Math.Min(target.Stats.MaxHp, target.Hp + formula.Healing(actorStats, heal.Power));
                events.Add(new BattleEvent("healed", actor.Id, target.Id, Amount: target.Hp - before));
                break;
            case RestoreMpEffect restore:
                target.Mp = Math.Clamp(target.Mp + restore.Amount, 0, target.Stats.MaxMp);
                break;
            case AddStatusEffect add:
                if (!statuses.TryGetValue(add.StatusId, out var status))
                    throw new KeyNotFoundException($"Unknown status '{add.StatusId}'.");
                if (random.RollBasisPoints() < Math.Clamp(add.ChanceBasisPoints, 0, 10_000))
                {
                    if (!target.Statuses.TryGetValue(add.StatusId, out var active))
                        target.Statuses[add.StatusId] = active = new ActiveStatus();
                    active.RemainingTurns = status.DefaultDuration;
                    active.Stacks = (byte)Math.Min(status.MaxStacks, active.Stacks + 1);
                    events.Add(new BattleEvent("status_added", actor.Id, target.Id, add.StatusId));
                }
                break;
            case RemoveStatusEffect remove:
                if (target.Statuses.Remove(remove.StatusId))
                    events.Add(new BattleEvent("status_removed", actor.Id, target.Id, remove.StatusId));
                break;
            case ReviveEffect revive when !target.Alive:
                target.Hp = Math.Max(1, Scale(target.Stats.MaxHp, Math.Clamp(revive.HealthBasisPoints, 0, 10_000)));
                events.Add(new BattleEvent("healed", actor.Id, target.Id, Amount: target.Hp));
                break;
        }
    }

    private void TickStatuses(
        BattleUnit unit,
        IReadOnlyDictionary<string, StatusDefinition> definitions,
        DeterministicRandom random,
        IBattleFormula formula,
        List<BattleEvent> events)
    {
        foreach (var (id, statusSnapshot) in unit.Statuses.ToArray())
        {
            if (!definitions.TryGetValue(id, out var definition))
                throw new KeyNotFoundException($"Unknown status '{id}'.");
            var periodic = new AbilityDefinition
            {
                Id = $"status.{id}",
                DisplayNameKey = id,
                TargetRule = TargetRule.SelfUnit,
                Effects = definition.PeriodicEffects
            };
            for (var stack = 0; stack < statusSnapshot.Stacks; stack++)
                foreach (var effect in definition.PeriodicEffects)
                    ApplyEffect(unit, unit.ResolveStats(definitions), unit, periodic, effect, definitions, random, formula, events);
            if (!unit.Statuses.TryGetValue(id, out var active)) continue;
            if (active.RemainingTurns > 0) active.RemainingTurns--;
            if (active.RemainingTurns == 0)
            {
                unit.Statuses.Remove(id);
                events.Add(new BattleEvent("status_removed", unit.Id, unit.Id, id));
            }
        }
    }

    private bool TargetsValid(BattleUnit actor, TargetRule rule, IReadOnlyList<string> ids)
    {
        if (ids.Count == 0 || ids.Distinct(StringComparer.Ordinal).Count() != ids.Count ||
            ids.Any(id => !Units.ContainsKey(id))) return false;
        var targets = ids.Select(GetUnit).ToList();
        var livingAllies = Units.Values.Count(unit => unit.Side == actor.Side && unit.Alive);
        var livingEnemies = Units.Values.Count(unit => unit.Side != actor.Side && unit.Alive);
        return rule switch
        {
            TargetRule.SelfUnit => ids.Count == 1 && ids[0] == actor.Id,
            TargetRule.SingleAlly => targets.Count == 1 && targets[0].Side == actor.Side && targets[0].Alive,
            TargetRule.AllAllies => targets.Count == livingAllies && targets.All(unit => unit.Side == actor.Side && unit.Alive),
            TargetRule.SingleEnemy => targets.Count == 1 && targets[0].Side != actor.Side && targets[0].Alive,
            TargetRule.AllEnemies => targets.Count == livingEnemies && targets.All(unit => unit.Side != actor.Side && unit.Alive),
            TargetRule.AnySingle => targets.Count == 1,
            _ => false
        };
    }

    private void RefreshPhase(List<BattleEvent> events)
    {
        var party = Units.Values.Any(unit => unit.Side == BattleSide.Party && unit.Alive);
        var enemy = Units.Values.Any(unit => unit.Side == BattleSide.Enemy && unit.Alive);
        var next = party && enemy ? BattlePhase.Running :
            party ? BattlePhase.PartyVictory : BattlePhase.EnemyVictory;
        if (next != Phase)
        {
            Phase = next;
            events.Add(new BattleEvent("phase_changed", DefinitionId: next.ToString()));
        }
    }

    private BattleUnit GetUnit(string id) => Units.TryGetValue(id, out var unit)
        ? unit
        : throw new KeyNotFoundException($"Unknown battle unit '{id}'.");

    private static uint SaturatingAdd(uint left, uint right) =>
        uint.MaxValue - left < right ? uint.MaxValue : left + right;
    private static uint SaturatingMultiply(uint left, uint right) =>
        left == 0 || right <= uint.MaxValue / left ? left * right : uint.MaxValue;
    private static int SaturatingMultiply(int left, int right) =>
        (int)Math.Clamp((long)left * right, int.MinValue, int.MaxValue);
    private static int Scale(int value, int basisPoints) =>
        (int)Math.Clamp((long)value * Math.Clamp(basisPoints, -20_000, 20_000) / 10_000, int.MinValue, int.MaxValue);
}

