public sealed class QuestJournal
{
    public Dictionary<string, QuestProgress> Quests { get; init; } = new(StringComparer.Ordinal);

    public void Start(QuestDefinition definition)
    {
        var progress = Quests.GetValueOrDefault(definition.Id) ?? new QuestProgress();
        progress.Status = QuestStatus.Active;
        foreach (var objective in definition.Objectives)
            progress.ObjectiveCounts.TryAdd(objective.Id, 0);
        Quests[definition.Id] = progress;
    }

    public bool Advance(QuestDefinition definition, string objectiveId, uint amount = 1)
    {
        if (!Quests.TryGetValue(definition.Id, out var progress) ||
            progress.Status != QuestStatus.Active)
            throw new InvalidOperationException($"Quest '{definition.Id}' is not active.");
        var objective = definition.Objectives.FirstOrDefault(item => item.Id == objectiveId) ??
            throw new KeyNotFoundException($"Unknown objective '{objectiveId}'.");
        progress.ObjectiveCounts[objectiveId] = Math.Min(
            objective.TargetCount,
            SaturatingAdd(progress.ObjectiveCounts.GetValueOrDefault(objectiveId), amount));
        return definition.Objectives.All(item =>
            progress.ObjectiveCounts.GetValueOrDefault(item.Id) >= item.TargetCount);
    }

    public void Complete(QuestDefinition definition)
    {
        if (!Quests.TryGetValue(definition.Id, out var progress) ||
            !definition.Objectives.All(item =>
                progress.ObjectiveCounts.GetValueOrDefault(item.Id) >= item.TargetCount))
            throw new InvalidOperationException($"Quest '{definition.Id}' has incomplete objectives.");
        progress.Status = QuestStatus.Completed;
    }

    private static uint SaturatingAdd(uint left, uint right) =>
        uint.MaxValue - left < right ? uint.MaxValue : left + right;
}

public sealed class StoryState
{
    public Dictionary<string, JsonElement> Flags { get; init; } = new(StringComparer.Ordinal);
    public QuestJournal Journal { get; init; } = new();

    public void Set<T>(string key, T value) =>
        Flags[key] = JsonSerializer.SerializeToElement(value, JrpgJson.Options);

    public T Get<T>(string key, T fallback = default!) =>
        Flags.TryGetValue(key, out var value)
            ? value.Deserialize<T>(JrpgJson.Options)!
            : fallback;
}

public sealed record DialogueChoice(
    string TextKey,
    string Next,
    string? RequiredBoolFlag = null,
    bool RequiredBoolValue = true);

public sealed class DialogueNode
{
    public required string Type { get; init; }
    public string? SpeakerId { get; init; }
    public string? TextKey { get; init; }
    public string? VoiceAsset { get; init; }
    public string? PortraitAsset { get; init; }
    public string? Next { get; init; }
    public List<DialogueChoice> Choices { get; init; } = new();
}

public sealed class DialogueGraph
{
    public required string Id { get; init; }
    public required string Entry { get; init; }
    public Dictionary<string, DialogueNode> Nodes { get; init; } = new(StringComparer.Ordinal);
}

public sealed record DialogueBeat(
    string Type,
    string? SpeakerId = null,
    string? TextKey = null,
    string? VoiceAsset = null,
    string? PortraitAsset = null,
    IReadOnlyList<(int Index, string TextKey)>? Choices = null);

public sealed class DialogueRunner
{
    public required string GraphId { get; init; }
    public required string CurrentNode { get; set; }
    public string? PendingNext { get; set; }

    public static DialogueRunner Start(DialogueGraph graph) =>
        new() { GraphId = graph.Id, CurrentNode = graph.Entry };

    public DialogueBeat Beat(DialogueGraph graph, StoryState story)
    {
        var node = graph.Nodes.GetValueOrDefault(CurrentNode) ??
            throw new KeyNotFoundException($"Unknown dialogue node '{CurrentNode}'.");
        return node.Type switch
        {
            "line" => Line(node),
            "choice" => new DialogueBeat(
                "choices",
                TextKey: node.TextKey,
                Choices: node.Choices
                    .Select((choice, index) => (choice, index))
                    .Where(pair => pair.choice.RequiredBoolFlag == null ||
                        story.Get(pair.choice.RequiredBoolFlag, false) == pair.choice.RequiredBoolValue)
                    .Select(pair => (pair.index, pair.choice.TextKey))
                    .ToList()),
            "end" => new DialogueBeat("end"),
            _ => throw new InvalidOperationException($"Unsupported dialogue node type '{node.Type}'.")
        };
    }

    public void AdvanceLine()
    {
        CurrentNode = PendingNext ??
            throw new InvalidOperationException("Dialogue is not waiting on a line.");
        PendingNext = null;
    }

    public void Choose(DialogueGraph graph, StoryState story, int index)
    {
        var node = graph.Nodes.GetValueOrDefault(CurrentNode) ??
            throw new KeyNotFoundException($"Unknown dialogue node '{CurrentNode}'.");
        if (node.Type != "choice" || index < 0 || index >= node.Choices.Count)
            throw new InvalidOperationException("Dialogue is not waiting on that choice.");
        var choice = node.Choices[index];
        if (choice.RequiredBoolFlag != null &&
            story.Get(choice.RequiredBoolFlag, false) != choice.RequiredBoolValue)
            throw new InvalidOperationException("Dialogue choice is unavailable.");
        CurrentNode = choice.Next;
    }

    private DialogueBeat Line(DialogueNode node)
    {
        PendingNext = node.Next ??
            throw new InvalidOperationException("Dialogue line has no next node.");
        return new DialogueBeat(
            "line",
            node.SpeakerId,
            node.TextKey,
            node.VoiceAsset,
            node.PortraitAsset);
    }
}

public sealed class EnemyFormation
{
    public required string Id { get; init; }
    public List<string> EnemyIds { get; init; } = new();
    public uint Weight { get; init; } = 1;
    public string? BattleScene { get; init; }
    public string? BattleMusic { get; init; }
}

public sealed class EncounterTable
{
    public required string Id { get; init; }
    public List<EnemyFormation> Formations { get; init; } = new();

    public EnemyFormation Choose(DeterministicRandom random)
    {
        var table = new WeightedTable<EnemyFormation>();
        foreach (var formation in Formations)
            if (formation.Weight > 0) table.Add(formation, formation.Weight);
        return table.Choose(random);
    }
}

public sealed class EncounterMeter
{
    public uint Progress { get; set; }
    public uint Threshold { get; init; } = 10_000;
    public bool Disabled { get; set; }

    public bool Advance(uint amount)
    {
        if (Threshold == 0) throw new InvalidOperationException("Encounter threshold is zero.");
        if (Disabled) return false;
        Progress = uint.MaxValue - Progress < amount ? uint.MaxValue : Progress + amount;
        if (Progress < Threshold) return false;
        Progress %= Threshold;
        return true;
    }
}

public sealed class LocalizationCatalog
{
    public required string FallbackLocale { get; init; }
    public Dictionary<string, Dictionary<string, string>> Locales { get; init; } =
        new(StringComparer.Ordinal);

    public string Resolve(
        string locale,
        string key,
        IReadOnlyDictionary<string, string>? tokens = null)
    {
        string? template = null;
        if (Locales.TryGetValue(locale, out var selected))
            selected.TryGetValue(key, out template);
        if (template == null && Locales.TryGetValue(FallbackLocale, out var fallback))
            fallback.TryGetValue(key, out template);
        if (template == null)
            throw new KeyNotFoundException($"Missing localization key '{key}' for '{locale}'.");
        if (tokens == null) return template;
        var result = template;
        foreach (var (token, value) in tokens.OrderBy(pair => pair.Key, StringComparer.Ordinal))
            result = result.Replace($"{{{token}}}", value, StringComparison.Ordinal);
        return result;
    }
}

[JsonPolymorphic(TypeDiscriminatorPropertyName = "type")]
[JsonDerivedType(typeof(PlaySequenceAnimation), "play_animation")]
[JsonDerivedType(typeof(PlaySequenceAudio), "play_audio")]
[JsonDerivedType(typeof(ActivateSequenceCamera), "activate_camera")]
[JsonDerivedType(typeof(FadeSequence), "fade")]
[JsonDerivedType(typeof(StartSequenceDialogue), "start_dialogue")]
[JsonDerivedType(typeof(LoadSequenceScene), "load_scene")]
[JsonDerivedType(typeof(CustomSequenceCommand), "custom")]
public abstract record SequenceCommand;
public sealed record PlaySequenceAnimation(
    string EntityId,
    string ClipAsset,
    bool Looping = false,
    float Speed = 1.0f) : SequenceCommand;
public sealed record PlaySequenceAudio(
    string EntityId,
    string ClipAsset,
    float Volume = 1.0f,
    bool Looping = false) : SequenceCommand;
public sealed record ActivateSequenceCamera(string CameraEntityId, uint BlendMilliseconds = 0) :
    SequenceCommand;
public sealed record FadeSequence(float From, float To, uint DurationMilliseconds) : SequenceCommand;
public sealed record StartSequenceDialogue(string DialogueId) : SequenceCommand;
public sealed record LoadSequenceScene(string SceneId) : SequenceCommand;
public sealed record CustomSequenceCommand(
    string Command,
    IReadOnlyDictionary<string, JsonElement>? Payload = null) : SequenceCommand;

[JsonPolymorphic(TypeDiscriminatorPropertyName = "type")]
[JsonDerivedType(typeof(WaitSequenceStep), "wait")]
[JsonDerivedType(typeof(EmitSequenceStep), "emit")]
public abstract record SequenceStep;
public sealed record WaitSequenceStep(uint DurationMilliseconds) : SequenceStep;
public sealed record EmitSequenceStep(SequenceCommand Command) : SequenceStep;

public sealed class SequenceDefinition
{
    public required string Id { get; init; }
    public List<SequenceStep> Steps { get; init; } = new();
}

public sealed class SequenceRunner
{
    public required string SequenceId { get; init; }
    public int NextStep { get; set; }
    public uint WaitRemainingMilliseconds { get; set; }
    public bool Finished { get; set; }

    public static SequenceRunner Start(SequenceDefinition sequence) =>
        new() { SequenceId = sequence.Id, Finished = sequence.Steps.Count == 0 };

    public IReadOnlyList<SequenceCommand> Advance(
        SequenceDefinition sequence,
        uint deltaMilliseconds)
    {
        var commands = new List<SequenceCommand>();
        if (Finished || SequenceId != sequence.Id) return commands;
        while (true)
        {
            if (WaitRemainingMilliseconds > 0)
            {
                var consumed = Math.Min(deltaMilliseconds, WaitRemainingMilliseconds);
                WaitRemainingMilliseconds -= consumed;
                deltaMilliseconds -= consumed;
                if (WaitRemainingMilliseconds > 0) break;
            }
            if (NextStep >= sequence.Steps.Count)
            {
                Finished = true;
                break;
            }
            switch (sequence.Steps[NextStep++])
            {
                case WaitSequenceStep wait:
                    WaitRemainingMilliseconds = wait.DurationMilliseconds;
                    if (deltaMilliseconds == 0 && WaitRemainingMilliseconds > 0)
                        return commands;
                    break;
                case EmitSequenceStep emit:
                    commands.Add(emit.Command);
                    break;
            }
        }
        return commands;
    }
}

public sealed class ActorDefinition
{
    public required string Id { get; init; }
    public required string DisplayNameKey { get; init; }
    public StatBlock BaseStats { get; init; } = new();
    public List<string> StartingAbilities { get; init; } = new();
    public string? FieldPrefab { get; init; }
    public string? BattlePrefab { get; init; }
}

public sealed class EnemyDefinition
{
    public required string Id { get; init; }
    public required string DisplayNameKey { get; init; }
    public StatBlock Stats { get; init; } = new();
    public List<string> Abilities { get; init; } = new();
    public ulong RewardExperience { get; init; }
    public ulong RewardCurrency { get; init; }
    public string? BattlePrefab { get; init; }
}

public sealed class JrpgDatabase
{
    public Dictionary<string, ActorDefinition> Actors { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, EnemyDefinition> Enemies { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, ItemDefinition> Items { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, AbilityDefinition> Abilities { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, StatusDefinition> Statuses { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, QuestDefinition> Quests { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, DialogueGraph> Dialogues { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, EncounterTable> Encounters { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, LocalizationCatalog> Localizations { get; init; } =
        new(StringComparer.Ordinal);
    public Dictionary<string, SequenceDefinition> Sequences { get; init; } =
        new(StringComparer.Ordinal);

    public static JrpgDatabase FromJson(string json)
    {
        var database = JsonSerializer.Deserialize<JrpgDatabase>(json, JrpgJson.Options) ??
            throw new InvalidOperationException("JRPG database JSON produced null.");
        database.Validate();
        return database;
    }

    public void Validate()
    {
        ValidateKeys(Actors, item => item.Id, "actor");
        ValidateKeys(Enemies, item => item.Id, "enemy");
        ValidateKeys(Items, item => item.Id, "item");
        ValidateKeys(Abilities, item => item.Id, "ability");
        ValidateKeys(Statuses, item => item.Id, "status");
        ValidateKeys(Quests, item => item.Id, "quest");
        ValidateKeys(Dialogues, item => item.Id, "dialogue");
        ValidateKeys(Encounters, item => item.Id, "encounter");
        ValidateKeys(Sequences, item => item.Id, "sequence");
        foreach (var item in Items.Values)
        {
            item.Validate();
            if (item.ConsumableAbility != null)
                Require(Abilities, item.ConsumableAbility, $"item '{item.Id}' ability");
            if (item.Equipment != null)
                foreach (var ability in item.Equipment.GrantedAbilities)
                    Require(Abilities, ability, $"item '{item.Id}' ability");
        }
        foreach (var ability in Abilities.Values)
        {
            ability.Validate();
            foreach (var effect in ability.Effects)
                ValidateEffect(effect, $"ability '{ability.Id}'");
        }
        foreach (var status in Statuses.Values)
        {
            if (status.DefaultDuration == 0 || status.MaxStacks == 0)
                throw new InvalidOperationException($"Invalid status '{status.Id}'.");
            foreach (var effect in status.PeriodicEffects)
                ValidateEffect(effect, $"status '{status.Id}'");
        }
        foreach (var actor in Actors.Values)
            foreach (var ability in actor.StartingAbilities)
                Require(Abilities, ability, $"actor '{actor.Id}' ability");
        foreach (var enemy in Enemies.Values)
            foreach (var ability in enemy.Abilities)
                Require(Abilities, ability, $"enemy '{enemy.Id}' ability");
        foreach (var table in Encounters.Values)
        {
            if (table.Formations.Select(item => item.Id).Distinct(StringComparer.Ordinal).Count() !=
                table.Formations.Count)
                throw new InvalidOperationException($"Encounter '{table.Id}' has duplicate formations.");
            foreach (var formation in table.Formations)
            {
                if (formation.Weight == 0 || formation.EnemyIds.Count == 0)
                    throw new InvalidOperationException($"Invalid formation '{formation.Id}'.");
                foreach (var enemy in formation.EnemyIds)
                    Require(Enemies, enemy, $"formation '{formation.Id}' enemy");
            }
        }
        foreach (var quest in Quests.Values)
        {
            if (quest.Objectives.Any(item => item.TargetCount == 0) ||
                quest.Objectives.Select(item => item.Id).Distinct(StringComparer.Ordinal).Count() !=
                quest.Objectives.Count)
                throw new InvalidOperationException($"Quest '{quest.Id}' has invalid objectives.");
        }
        foreach (var graph in Dialogues.Values)
        {
            if (!graph.Nodes.ContainsKey(graph.Entry))
                throw new InvalidOperationException($"Dialogue '{graph.Id}' has no entry node.");
            foreach (var node in graph.Nodes.Values)
            {
                IEnumerable<string> next = node.Type == "choice"
                    ? node.Choices.Select(choice => choice.Next)
                    : node.Next == null ? Array.Empty<string>() : new[] { node.Next };
                foreach (var nodeId in next)
                    if (!graph.Nodes.ContainsKey(nodeId))
                        throw new InvalidOperationException(
                            $"Dialogue '{graph.Id}' references missing node '{nodeId}'.");
            }
        }
        foreach (var (id, catalog) in Localizations)
            if (string.IsNullOrEmpty(catalog.FallbackLocale) ||
                !catalog.Locales.ContainsKey(catalog.FallbackLocale))
                throw new InvalidOperationException(
                    $"Localization '{id}' has no fallback locale '{catalog.FallbackLocale}'.");
        foreach (var sequence in Sequences.Values)
            foreach (var step in sequence.Steps.OfType<EmitSequenceStep>())
                ValidateSequenceCommand(sequence.Id, step.Command);
    }

    private void ValidateEffect(BattleEffect effect, string owner)
    {
        switch (effect)
        {
            case DamageEffect damage when damage.Power <= 0:
            case HealEffect heal when heal.Power <= 0:
                throw new InvalidOperationException($"{owner} has non-positive effect power.");
            case AddStatusEffect add:
                if (add.ChanceBasisPoints is < 0 or > 10_000)
                    throw new InvalidOperationException($"{owner} has an invalid status chance.");
                Require(Statuses, add.StatusId, $"{owner} status");
                break;
            case RemoveStatusEffect remove:
                Require(Statuses, remove.StatusId, $"{owner} status");
                break;
            case ReviveEffect revive when revive.HealthBasisPoints is <= 0 or > 10_000:
                throw new InvalidOperationException($"{owner} has an invalid revive percentage.");
        }
    }

    private static void ValidateSequenceCommand(string sequenceId, SequenceCommand command)
    {
        var valid = command switch
        {
            PlaySequenceAnimation item =>
                !string.IsNullOrEmpty(item.EntityId) && !string.IsNullOrEmpty(item.ClipAsset) &&
                float.IsFinite(item.Speed) && item.Speed > 0.0f,
            PlaySequenceAudio item =>
                !string.IsNullOrEmpty(item.EntityId) && !string.IsNullOrEmpty(item.ClipAsset) &&
                float.IsFinite(item.Volume) && item.Volume is >= 0.0f and <= 1.0f,
            ActivateSequenceCamera item => !string.IsNullOrEmpty(item.CameraEntityId),
            FadeSequence item =>
                float.IsFinite(item.From) && float.IsFinite(item.To) &&
                item.From is >= 0.0f and <= 1.0f && item.To is >= 0.0f and <= 1.0f,
            StartSequenceDialogue item => !string.IsNullOrEmpty(item.DialogueId),
            LoadSequenceScene item => !string.IsNullOrEmpty(item.SceneId),
            CustomSequenceCommand item => !string.IsNullOrEmpty(item.Command),
            _ => false
        };
        if (!valid)
            throw new InvalidOperationException($"Sequence '{sequenceId}' contains an invalid command.");
    }

    private static void ValidateKeys<T>(
        IReadOnlyDictionary<string, T> values,
        Func<T, string> id,
        string kind)
    {
        foreach (var (key, value) in values)
            if (key != id(value))
                throw new InvalidOperationException($"{kind} key '{key}' does not match '{id(value)}'.");
    }

    private static void Require<T>(IReadOnlyDictionary<string, T> values, string id, string owner)
    {
        if (!values.ContainsKey(id))
            throw new InvalidOperationException($"{owner} references missing '{id}'.");
    }
}

public sealed class JrpgSession
{
    public const int CurrentSchemaVersion = 1;

    public int SchemaVersion { get; init; } = CurrentSchemaVersion;
    public Party Party { get; init; } = new();
    public Inventory Inventory { get; init; } = new();
    public StoryState Story { get; init; } = new();
    public Dictionary<string, EncounterMeter> EncounterMeters { get; init; } = new(StringComparer.Ordinal);
    public BattleSession? Battle { get; set; }
    public DeterministicRandom Random { get; init; }

    public JrpgSession(ulong seed = 0) => Random = new DeterministicRandom(seed);

    public string ToJson() => JsonSerializer.Serialize(this, JrpgJson.Options);

    public static JrpgSession FromJson(string json)
    {
        var session = JsonSerializer.Deserialize<JrpgSession>(json, JrpgJson.Options) ??
            throw new InvalidOperationException("JRPG session JSON produced null.");
        if (session.SchemaVersion != CurrentSchemaVersion)
            throw new InvalidOperationException($"Unsupported JRPG schema {session.SchemaVersion}.");
        return session;
    }

    public void Recruit(JrpgDatabase database, string actorId, bool preferActive = true)
    {
        var definition = database.Actors.GetValueOrDefault(actorId) ??
            throw new KeyNotFoundException($"Unknown actor '{actorId}'.");
        var actor = new CharacterProgress
        {
            ActorId = definition.Id,
            DisplayNameKey = definition.DisplayNameKey,
            BaseStats = definition.BaseStats.Clamp()
        };
        actor.LearnedAbilities.UnionWith(definition.StartingAbilities);
        Party.Recruit(actor, preferActive);
    }
}

/// Convenience adapters between the pure JRPG state and the frame-safe script bridge.
public static class JrpgScriptTools
{
    public static LogicAssetQuery QueryDatabase(EngineBehaviour behaviour, string assetId) =>
        behaviour.LogicAssets.Query(assetId);

    public static bool TryGetDatabase(
        EngineBehaviour behaviour,
        LogicAssetQuery query,
        out JrpgDatabase database)
    {
        if (behaviour.LogicAssets.TryGetJson(query, out var json))
        {
            database = JrpgDatabase.FromJson(json);
            return true;
        }
        database = null!;
        return false;
    }

    public static void SaveSession(
        EngineBehaviour behaviour,
        string slot,
        JrpgSession session) =>
        behaviour.Save.SaveJson(slot, session.ToJson());

    public static bool TryRestoreSession(
        EngineBehaviour behaviour,
        string slot,
        out JrpgSession session)
    {
        if (behaviour.Save.TryGetLoadedJson(slot, out var json))
        {
            session = JrpgSession.FromJson(json);
            return true;
        }
        session = null!;
        return false;
    }

    /// Executes sequence commands backed by existing engine APIs. Camera
    /// blends, fades, dialogue UI, and custom commands intentionally return
    /// false so the project can route them through its presentation layer.
    public static bool TryExecuteSequenceCommand(
        EngineBehaviour behaviour,
        SequenceCommand command)
    {
        switch (command)
        {
            case PlaySequenceAnimation animation:
                behaviour.Animation.PlayClip(
                    animation.EntityId,
                    animation.ClipAsset,
                    animation.Looping,
                    animation.Speed);
                return true;
            case PlaySequenceAudio audio:
                behaviour.Audio.Play(
                    audio.EntityId,
                    audio.ClipAsset,
                    audio.Volume,
                    audio.Looping);
                return true;
            case LoadSequenceScene scene:
                behaviour.Scene.Load(scene.SceneId);
                return true;
            default:
                return false;
        }
    }
}
